<script setup>
import {ref,shallowRef,computed,onMounted,onBeforeUnmount} from 'vue'
import L from 'leaflet'
import NavigationApp from './NavigationApp.vue'
import {phase,inside,arrivalTime,parkingTotals,parkingLabelPoint} from './simulationMath'
import {drawActor,drawFlowPath} from './trafficArt'
import {ScreenRoutes} from './simulationRender'
const el=ref(null),canvas=ref(null),data=shallowRef(null),error=ref(''),loading=ref(true),view=ref('simulation'),scenario=ref('baseline'),playing=ref(true),time=ref(0),speed=ref(20),showLots=ref(true),showMetrics=ref(true),selected=ref(null),sharedMap=shallowRef(null),count=ref(Math.max(100,Math.min(1000,Number(localStorage.getItem('campusflow.animation.count'))||1000)))
const stats=shallowRef({moving:0,parked:0,over:0,loads:{},illegal:{},groups:{}})
let mapMoving=false,map,placeLayer,lotLayer,badgeLayer,frame,previous=0,lastRender=0,lastStats=0,lastFlow=0,simTime=0,controller,resize,disposed=false,badges=[],routes,fleetCanvas,flowCanvas,fleetDirty=true,needsPaint=true,parkSpots=new Map(),canvasSize={w:0,h:0}
const agents=computed(()=>data.value?.cases[scenario.value]||[])
const visibleAgents=computed(()=>[...agents.value].sort((a,b)=>((Math.imul(a.id+1,2654435761)>>>0)-(Math.imul(b.id+1,2654435761)>>>0))).slice(0,count.value))
const areaLookup=computed(()=>new Map((data.value?.areas||[]).map(a=>[a.id,a])))
const destinationLookup=computed(()=>new Map((data.value?.destinations||[]).map(p=>[p.id,p])))
const clock=computed(()=>`08:${String(Math.floor(time.value/60)).padStart(2,'0')}:${String(Math.floor(time.value%60)).padStart(2,'0')}`)
const groups=['修远','明远','鸿远']
const parkingRanks=computed(()=>{const counts=new Map(),ranks=new Map();for(const a of [...agents.value].filter(a=>a.area_id).sort((a,b)=>(a.start+a.travel_seconds)-(b.start+b.travel_seconds)||a.id-b.id)){const key=a.area_id+'/'+!!a.illegal,i=counts.get(key)||0;counts.set(key,i+1);ranks.set(a.id,i)}return ranks})
const trailGroups=computed(()=>{const result=new Map();function add(a,path,mode,start,duration){if(path==null)return;const key=path+'/'+mode;if(!result.has(key))result.set(key,{path,mode,members:[]});result.get(key).members.push({start,duration,finish:start+duration})}for(const a of visibleAgents.value){add(a,a.path,a.mode,a.start,a.travel_seconds);if(a.walk_path!=null)add(a,a.walk_path,'walk',a.start+a.travel_seconds+60,data.value.paths[a.walk_path].seconds)}return [...result.values()]})
const metricFor=area=>{const total=Math.round(stats.value.loads[area.id]||0),illegal=Math.min(total,Math.round(stats.value.illegal[area.id]||0));return {total,illegal,percent:Math.round(total/area.capacity*100),illegalRate:total?Math.round(illegal/total*100):0}}
const colorFor=p=>p>=100?'#d93025':p>=80?'#c58225':'#22804a'
function context(c){return c.getContext('2d')}
function clear(c){context(c).clearRect(0,0,canvasSize.w,canvasSize.h)}
function projection(){if(!map||!fleetCanvas||!flowCanvas)return;routes?.clear();parkSpots.clear();const origin=map.containerPointToLayerPoint([0,0]),size=map.getSize(),dpr=Math.min(devicePixelRatio,1.5);canvasSize={w:size.x,h:size.y};for(const c of [canvas.value,fleetCanvas,flowCanvas]){L.DomUtil.setPosition(c,origin);c.width=size.x*dpr;c.height=size.y*dpr;c.style.width=size.x+'px';c.style.height=size.y+'px';context(c).setTransform(dpr,0,0,dpr,0,0)}fleetDirty=true;needsPaint=true;lastFlow=0}
function pixel(path,p){return routes.sample(path,p)}
function onScreen(p,pad=60){return p.x>=-pad&&p.y>=-pad&&p.x<=canvasSize.w+pad&&p.y<=canvasSize.h+pad}
function lerp(a,b,t){return {x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t}}
function slots(area,illegal=false){const key=area.id+'/'+illegal;if(parkSpots.has(key))return parkSpots.get(key);const ring=area.geometry.coordinates[0].map(p=>map.latLngToContainerPoint([p[1],p[0]])),xy=ring.map(p=>[p.x,p.y]),xs=ring.map(p=>p.x),ys=ring.map(p=>p.y),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys),points=[];let seed=area.id.split('').reduce((a,c)=>a+c.charCodeAt(0),illegal?73:1);const random=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296};const allRings=illegal?data.value.areas.map(a=>a.geometry.coordinates[0].map(p=>{const q=map.latLngToContainerPoint([p[1],p[0]]);return[q.x,q.y]})):null;for(let i=0;i<2200&&points.length<150;i++){let x,y;if(illegal){const side=i%4,gap=5+random()*12;if(side<2){x=side?maxX+gap:minX-gap;y=minY+random()*(maxY-minY)}else{x=minX+random()*(maxX-minX);y=side===2?minY-gap:maxY+gap}}else{x=minX+random()*(maxX-minX);y=minY+random()*(maxY-minY)}if(illegal?!allRings.some(r=>inside([x,y],r)):inside([x,y],xy))points.push({x,y})}parkSpots.set(key,points);return points}
function parkedPoint(a){const area=areaLookup.value.get(a.area_id),points=slots(area,!!a.illegal);return points[(parkingRanks.value.get(a.id)||0)%Math.max(1,points.length)]||map.latLngToContainerPoint([area.latitude,area.longitude])}
function positionLabels(){if(!map||!data.value)return;const used=[],bounds=new Map(data.value.areas.map(a=>{const ring=a.geometry.coordinates[0].map(p=>map.latLngToContainerPoint([p[1],p[0]])),xs=ring.map(p=>p.x),ys=ring.map(p=>p.y);return[a.id,{ring,minX:Math.min(...xs),maxX:Math.max(...xs),minY:Math.min(...ys),maxY:Math.max(...ys)}]}));for(const b of badges){const box=bounds.get(b.area.id),pos=parkingLabelPoint(box.ring,map.getZoom()),w=78*pos.scale,h=34*pos.scale;let x=pos.x,y=pos.y;if(pos.outside){const options=[];for(let i=0;i<7;i++){const shift=(i%2?-1:1)*Math.ceil(i/2)*(w+5);options.push({x:pos.x+shift,y:pos.y},{x:box.maxX+14+w/2,y:(box.minY+box.maxY)/2+shift},{x:box.minX-14-w/2,y:(box.minY+box.maxY)/2+shift},{x:pos.x+shift,y:box.maxY+14+h/2})}const score=p=>{let cost=Math.hypot(p.x-pos.x,p.y-pos.y)*.1;for(const r of used)if(Math.abs(r.x-p.x)<(r.w+w)/2+3&&Math.abs(r.y-p.y)<(r.h+h)/2+3)cost+=10000;for(const r of bounds.values())if(p.x+w/2>r.minX-3&&p.x-w/2<r.maxX+3&&p.y+h/2>r.minY-3&&p.y-h/2<r.maxY+3)cost+=2000;if(p.x<w/2||p.y<h/2||p.x>canvasSize.w-w/2||p.y>canvasSize.h-h/2)cost+=300;return cost};options.sort((a,b)=>score(a)-score(b));({x,y}=options[0])}else for(let step=0;step<12&&used.some(r=>Math.abs(r.x-x)<(r.w+w)/2+3&&Math.abs(r.y-y)<(r.h+h)/2+3);step++)x=pos.x+(step%2?-1:1)*Math.ceil((step+1)/2)*(w+5);used.push({x,y,w,h});b.marker.setLatLng(map.containerPointToLatLng([x,y]));b.node.style.setProperty('--badge-scale',pos.scale);if(pos.outside){const anchor=[Math.max(box.minX,Math.min(box.maxX,x)),Math.max(box.minY,Math.min(box.maxY,y))];b.leader.setLatLngs([map.containerPointToLatLng(anchor),map.containerPointToLatLng([x,y])]);b.leader.setStyle({opacity:.55})}else b.leader.setStyle({opacity:0})}}

function updateStats(){if(!data.value)return;const {loads,illegal}=parkingTotals(agents.value,simTime,1),g={};let moving=0;for(const a of agents.value){if(simTime<a.start||simTime>=arrivalTime(a,data.value.paths))continue;moving++;const name=areaLookup.value.get(a.area_id)?.name.slice(0,2)||a.destination_name.slice(0,2);g[name]=(g[name]||0)+1}stats.value={loads,illegal,moving,parked:Math.round(Object.values(loads).reduce((a,b)=>a+b,0)),over:data.value.areas.filter(a=>(loads[a.id]||0)>a.capacity).length,groups:g};time.value=simTime;for(const b of badges){const m=metricFor(b.area),text=m.percent+'%',sub=`违停 ${m.illegal} · ${m.illegalRate}%`;if(b.valueNode.textContent!==text)b.valueNode.textContent=text;if(b.illegalNode.textContent!==sub)b.illegalNode.textContent=sub;const color=colorFor(m.percent);if(b.color!==color){b.color=color;b.node.style.setProperty('--pin-color',color);b.layer.setStyle({color,fillOpacity:m.percent>=100?.25:.1})}}fleetDirty=true}
function paintFleet(){clear(fleetCanvas);const ctx=context(fleetCanvas),zoom=map.getZoom(),size=zoom>=18?.86:zoom>=17?.68:.4;if(!showLots.value)return;for(const a of visibleAgents.value)if(a.area_id&&simTime>=a.start+a.travel_seconds+18){const p=parkedPoint(a);if(onScreen(p))drawActor(ctx,p,a.mode,size*.72,0,1,false,0)}}
function paintFlows(){clear(flowCanvas);const ctx=context(flowCanvas);for(const group of trailGroups.value){let progress=-1,alpha=0;for(const m of group.members){if(simTime<m.start||simTime>m.finish+24)continue;progress=Math.max(progress,Math.min(1,(simTime-m.start)/m.duration));alpha=Math.max(alpha,simTime<=m.finish+12?1:Math.max(0,(m.finish+24-simTime)/12))}if(progress>=0)drawFlowPath(ctx,routes.trace(group.path,progress),group.mode,simTime,alpha,{sample:p=>routes.sample(group.path,p),progress,seed:Number(group.path)||0})}}
function draw(now){frame=requestAnimationFrame(draw);if(!map||!data.value||mapMoving){previous=now;return}if(now-lastRender<1000/30)return;lastRender=now;if(!playing.value&&!needsPaint){previous=now;return}const delta=previous?Math.min((now-previous)/1000,.2):0;previous=now;if(playing.value){simTime=Math.min(1800,simTime+delta*speed.value);if(simTime===1800)playing.value=false}if(now-lastStats>250||needsPaint){updateStats();lastStats=now}if(fleetDirty){paintFleet();fleetDirty=false}if(now-lastFlow>65||needsPaint){paintFlows();lastFlow=now}needsPaint=false;const ctx=context(canvas.value);clear(canvas.value);const zoom=map.getZoom(),size=zoom>=18?.86:zoom>=17?.68:.48;for(const a of visibleAgents.value){const state=phase(a,simTime,data.value.paths);let p,angle=0,alpha=1;if(state.kind==='parking'){const spot=parkedPoint(a);p=lerp(pixel(a.path,1),spot,1-Math.pow(1-state.progress,2))}else if(state.kind==='dismount'){const spot=parkedPoint(a);p={x:spot.x+14*size,y:spot.y-5*size};alpha=Math.min(1,state.progress*4);if(onScreen(p)&&zoom>=17){ctx.font='11px "PingFang SC","HarmonyOS_Regular","Helvetica Neue","Microsoft YaHei",sans-serif';ctx.fillStyle='#79583d';ctx.fillText('下车',p.x+10,p.y-13)}}else if(state.kind==='leaving'){const spot=parkedPoint(a),side={x:spot.x+14*size,y:spot.y-5*size};p=lerp(side,a.walk_path?pixel(a.walk_path,0):side,state.progress)}else if(state.kind==='entering'){const end=pixel(a.walk_path||a.path,1),goal=destinationLookup.value.get(a.destination_id),dest=goal?map.latLngToContainerPoint([goal.latitude,goal.longitude]):end;p=lerp(end,dest,state.progress);alpha=1-state.progress*.8}else if(['moving','walking'].includes(state.kind)){p=pixel(state.path,state.progress);const prev=pixel(state.path,Math.max(0,state.progress-.005));angle=Math.atan2(p.y-prev.y,p.x-prev.x)}else continue;if(p&&onScreen(p))drawActor(ctx,p,['moving','parking'].includes(state.kind)?a.mode:'walk',size,angle,alpha,true,simTime)}}
function buildLots(){lotLayer.clearLayers();badgeLayer.clearLayers();badges=[];for(const area of data.value.areas){const layer=L.geoJSON(area.geometry,{style:{color:'#22804a',weight:1.7,fillOpacity:.1}}).addTo(lotLayer);layer.on('click',()=>focus(area));const node=document.createElement('button');node.className='sim-parking-pin';node.title=area.name;node.setAttribute('aria-label',area.name);const letter=document.createElement('b');letter.textContent='P';const numbers=document.createElement('span'),valueNode=document.createElement('strong'),illegalNode=document.createElement('small');numbers.append(valueNode,illegalNode);node.append(letter,numbers);node.onclick=()=>focus(area);const marker=L.marker([area.latitude,area.longitude],{icon:L.divIcon({html:node,className:'sim-parking-icon',iconSize:[0,0]}),title:area.name}).addTo(badgeLayer),leader=L.polyline([],{color:'#74796c',weight:1,dashArray:'3 4',interactive:false}).addTo(badgeLayer);const tooltip=document.createElement('span');tooltip.textContent=area.name;marker.bindTooltip(tooltip,{direction:'top'});badges.push({area,node,valueNode,illegalNode,marker,leader,layer})}toggleLots();positionLabels()}
function focus(area){selected.value=area;map.flyTo([area.latitude,area.longitude],19,{duration:.7})}
function toggleLots(){if(!map)return;for(const [layer,visible] of [[lotLayer,showLots.value],[badgeLayer,showMetrics.value]]){if(visible)layer.addTo(map);else map.removeLayer(layer)}fleetDirty=true;needsPaint=true}
function fit(){if(!data.value)return;const bounds=L.latLngBounds(data.value.areas.flatMap(a=>a.geometry.coordinates[0].map(p=>[p[1],p[0]])));for(const a of agents.value){const p=data.value.paths[a.path].coordinates[0];bounds.extend([p[1],p[0]])}const narrow=map.getSize().x<720;map.fitBounds(bounds,{paddingTopLeft:[20,100],paddingBottomRight:[narrow?20:280,narrow?250:175],maxZoom:17})}
function restart(){simTime=0;time.value=0;playing.value=true;previous=0;needsPaint=true;updateStats()}
function seek(){simTime=time.value;previous=0;needsPaint=true;lastFlow=0;updateStats()}
function togglePlay(){playing.value=!playing.value;previous=0;needsPaint=true}
function switchCase(value){scenario.value=value;selected.value=null;restart()}
async function load(){controller?.abort();controller=new AbortController();const token=controller;loading.value=true;error.value='';try{const r=await fetch('/api/simulation/morning?population=4000&count='+count.value,{signal:controller.signal});const d=await r.json();if(!r.ok)throw Error(d.detail||'交通动画加载失败');if(disposed||token!==controller)return;data.value=d;routes=new ScreenRoutes(map,d.paths);parkSpots.clear();placeLayer.clearLayers();for(const [items,tone] of [[d.origins||[],'#6e7e65'],[d.destinations||[],'#8e7858']])for(const p of items){const label=document.createElement('span');label.textContent=p.name;L.circleMarker([p.latitude,p.longitude],{radius:3,color:'white',weight:1,fillColor:tone,fillOpacity:1}).bindTooltip(label,{direction:'top'}).addTo(placeLayer)}buildLots();fit();restart()}catch(e){if(e.name!=='AbortError')error.value=e.message}finally{if(token===controller)loading.value=false}}
function settings(){const value=Number(localStorage.getItem('campusflow.animation.count'));if(value>=100&&value<=1000&&value!==count.value){count.value=value;needsPaint=true;fleetDirty=true;lastFlow=0}}
function openNavigation(){view.value='navigation';playing.value=false;selected.value=null;previous=0;needsPaint=true}
function navBack(){view.value='simulation'}
function addCanvas(name,z,existing){const pane=map.createPane(name);pane.style.zIndex=z;pane.style.pointerEvents='none';const c=existing||document.createElement('canvas');c.className='traffic-canvas';pane.appendChild(c);return c}
onMounted(async()=>{map=L.map(el.value,{zoomControl:false,zoomSnap:.25,center:[34.372,108.899],zoom:16});sharedMap.value=map;flowCanvas=addCanvas('traffic-paths',440);fleetCanvas=addCanvas('traffic-parked',450);addCanvas('traffic-actors',460,canvas.value);L.control.zoom({position:'bottomright'}).addTo(map);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:20,maxNativeZoom:19,attribution:'© OpenStreetMap contributors'}).addTo(map);lotLayer=L.layerGroup().addTo(map);badgeLayer=L.layerGroup().addTo(map);placeLayer=L.layerGroup().addTo(map);map.on('movestart zoomstart',()=>{mapMoving=true});map.on('resize',projection);map.on('moveend zoomend',()=>{mapMoving=false;projection();positionLabels();needsPaint=true});resize=new ResizeObserver(()=>{map.invalidateSize();projection();positionLabels()});resize.observe(el.value);projection();frame=requestAnimationFrame(draw);document.fonts.ready.then(()=>{if(!disposed){needsPaint=true;fleetDirty=true}});window.addEventListener('storage',settings);try{const r=await fetch('/api/navigation/map');if(!r.ok)throw Error('道路图层加载失败');const d=await r.json();if(disposed)return;const names=new Set();L.geoJSON(d,{style:f=>({color:f.properties.name==='修远大道'?'#e9a149':f.properties.highway==='cycleway'?'#339361':['footway','pedestrian','steps'].includes(f.properties.highway)?'#a3947c':'#e9a149',weight:3,opacity:.8}),onEachFeature(f,l){const n=f.properties.name;if(n&&!names.has(n)){names.add(n);const text=document.createElement('span');text.textContent=n;l.bindTooltip(text,{permanent:true,direction:'center',className:'sim-road-name'})}}}).addTo(map);await load()}catch(e){error.value=e.message;loading.value=false}})
onBeforeUnmount(()=>{disposed=true;controller?.abort();cancelAnimationFrame(frame);window.removeEventListener('storage',settings);resize?.disconnect();map?.remove()})
</script>
<template>
 <div class="morning-app" :class="{navigating:view==='navigation'}">
  <div ref="el" class="morning-map"></div><canvas ref="canvas" class="traffic-canvas" aria-label="沿校园路网运行的行人、自行车和电动车交通动画"></canvas>
  <header class="morning-header"><div><strong>CampusFlow</strong><span>渭水校区 / 早高峰交通演示</span></div><nav><button :class="{chosen:scenario==='baseline'}" @click="switchCase('baseline')">01 原有停车习惯</button><button :class="{chosen:scenario==='guided'}" @click="switchCase('guided')">02 系统引导分流</button><button @click="openNavigation">地点与导航</button></nav></header>
  <aside v-if="view!=='navigation'" class="morning-explainer"><small>08:00—08:30 · 校园早高峰</small><h1>{{scenario==='baseline'?'人流汇入，停车失衡':'改变停车选择，缓解集中'}}</h1><p>宿舍出发 → 沿路网通行 → 停车 → 步行至教学楼</p><div class="type-key"><span style="color:#725aad">● 行人 · 紫色流光</span><span style="color:#198755">● 自行车 · 绿色流光</span><span style="color:#dc6c24">● 电动车 · 橙色流光</span></div><p>点击 P 放大：看车辆汇入、停下与人车分离。拖动时间可回看停车形成过程。</p><label><input type="checkbox" v-model="showLots" @change="toggleLots">停车区域与车辆</label><label><input type="checkbox" v-model="showMetrics" @change="toggleLots">容载率与违停率</label><a href="/debug" target="_blank" rel="noopener">调试动效数量 ↗</a></aside>
  <div v-if="loading||error" class="morning-message" role="status">{{error||'正在按校园路网生成出行轨迹…'}}<button v-if="error" @click="load">重新加载</button></div>
  <aside v-if="selected" class="parking-closeup"><button class="close" @click="selected=null">×</button><small>停车区近景</small><h2>{{selected.name}}</h2><strong v-if="showMetrics">{{metricFor(selected).percent}}%</strong><p v-if="showMetrics">停放 {{metricFor(selected).total}} / 容量 {{selected.capacity}}<br>违停 {{metricFor(selected).illegal}} 辆 · {{metricFor(selected).illegalRate}}%</p><p>车辆进入停车区并停下，人在车旁出现，再走向教学楼。区域外车辆为归属该停车区的违停车辆。</p></aside>
  <footer class="morning-footer"><div class="time-controls"><button @click="togglePlay" :disabled="!data">{{playing?'暂停':'播放'}}</button><button @click="restart" :disabled="!data">重播</button><b>{{clock}}</b><input aria-label="早高峰时间轴" type="range" min="0" max="1800" step="1" :disabled="!data" v-model.number="time" @input="seek"><select v-model.number="speed" aria-label="播放速度"><option :value="10">10倍</option><option :value="20">20倍</option><option :value="40">40倍</option><option :value="60">60倍</option></select></div>
   <div class="traffic-summary"><div class="summary-total"><span>总体交通状态</span><b>{{stats.moving}} 人在途 · {{stats.parked}} 辆停放</b><small>{{stats.over}} 处超容量 · {{data?.generated_agents||0}} 人 · {{data?.vehicle_count||0}} 辆车 · 图标上限 {{count}}</small></div><div v-for="g in groups" :key="g" class="flow-group"><span>{{g}}教学片区</span><div class="wave" :class="{paused:!playing}"><i v-for="i in 16" :key="i" :style="{'--height':(5+((stats.groups[g]||0)*3+i*7)%27)+'px','--delay':i*-.12+'s',opacity:(stats.groups[g]||0)?1:.2}"></i></div><small>{{stats.groups[g]||0}} 人流动</small></div><div class="road-types"><span><i style="background:#339361"></i>自行车道</span><span><i style="background:#e9a149"></i>通用道路</span><span><i style="background:#a3947c"></i>步行道</span></div></div>
   <p class="simulation-source">统计按每辆车逐辆计算；地图图标为抽样展示。<br>{{data?.covered_dorms||0}} 栋宿舍 · 轨迹抵达目的地后延迟消失 <span v-if="data?.excluded.length">· {{data.excluded.length}} 条需求暂不可达</span></p>
  </footer>
  <NavigationApp v-if="view==='navigation'&&sharedMap" :shared-map="sharedMap" :traffic-context="{time_seconds:time,scenario,count,seed:data?.seed||20261016,population:data?.population||4000}" @close="navBack"/>
 </div>
